import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_default():
    @click.command()
    def cli_raises():
        raise ValueError("This is an intentional error.")

    runner = CliRunner()
    result = runner.invoke(cli_raises)
    assert result.exception is not None
    assert isinstance(result.exception, ValueError)

def test_runner_catch_exceptions_false_on_runner():
    @click.command()
    def cli_raises():
        raise ValueError("This is an intentional error.")

    runner = CliRunner(catch_exceptions=False)
    with pytest.raises(ValueError, match="This is an intentional error."):
        runner.invoke(cli_raises)

def test_runner_catch_exceptions_override_on_invoke():
    @click.command()
    def cli_raises():
        raise ValueError("This is an intentional error.")

    runner = CliRunner(catch_exceptions=True)  # Should be overridden by invoke
    with pytest.raises(ValueError, match="This is an intentional error."):
        runner.invoke(cli_raises, catch_exceptions=False)

import pytest
import click


def test_func_param_type_value_error_message(runner):
    class MyClass:
        def __init__(self, value):
            self.value = value

        @staticmethod
        def from_str(input_value: str) -> "MyClass":
            if input_value != "works":
                raise ValueError(f"input was {input_value!r}, should be 'works'")
            return MyClass(input_value)

    @click.command()
    @click.argument("mydata", type=click.types.FuncParamType(MyClass.from_str))
    def cli(mydata):
        click.echo(f"Success: {mydata.value}")

    result = runner.invoke(cli, ["fails"])
    assert "Error: Invalid value for 'MYDATA': input was 'fails', should be 'works'" in result.output

from tests.dialects.test_dialect import Validator
import unittest
from sqlglot import parse_one, exp


class TestMysql8225(Validator):
    def test_create_table_auto_increment(self):
        sql = """CREATE TABLE t1(id INT KEY AUTO_INCREMENT);"""
        # The bug causes a ParseError. We assert that it parses without error.
        # The specific AST structure is less important than the fact it parses.
        try:
            parse_one(sql, read="mysql")
        except Exception as e:
            self.fail(f"Parsing CREATE TABLE with AUTO_INCREMENT failed: {e}")
